INSERT INTO products (id, name, slug, category_id, short_description, description, features, specifications, price, show_price, main_image, is_featured, is_published, is_demo, seo_title, seo_description, display_order) VALUES
(1, 'Solar Street Light', 'solar-street-light', 1,
 'A solar-powered street lighting option for roads, compounds and commercial premises.',
 'Solar street lighting provides an off-grid lighting option for roads, factory compounds, car parks and commercial premises. GTC Holdings supplies solar street lighting for retail and wholesale buyers across Sri Lanka.\n\nPlease contact our team for the models, sizes and technical details currently available.',
 '[{"title":"Retail and wholesale supply","text":"Available for single-unit and bulk requirements."},{"title":"Specifications on request","text":"Contact us for the models and technical details currently in stock."}]',
 NULL, NULL, 0, 'uploads/seed/prod-solar-street.webp', 1, 1, 1,
 'Solar Street Light in Sri Lanka | GTC Holdings', 'Solar street lighting for roads, compounds and commercial premises. Contact GTC Holdings for available models and pricing.', 1),
(2, 'Solar Flood Light', 'solar-flood-light', 1,
 'A solar flood lighting option for gardens, driveways, warehouses and outdoor areas.',
 'Solar flood lights are suitable for gardens, driveways, warehouse yards and other outdoor areas where mains power is inconvenient. GTC Holdings supplies solar flood lighting for homes, businesses and resellers.\n\nContact us for the available models and current pricing.',
 '[{"title":"Outdoor use","text":"Suitable for gardens, yards and commercial premises."},{"title":"Supply options","text":"Available for retail and wholesale buyers."}]',
 NULL, NULL, 0, 'uploads/seed/prod-solar-flood.webp', 1, 1, 1,
 'Solar Flood Light in Sri Lanka | GTC Holdings', 'Solar flood lighting for gardens, driveways, warehouses and outdoor areas. Contact GTC Holdings for models and pricing.', 2),
(3, 'Solar Garden Light', 'solar-garden-light', 1,
 'Decorative and practical solar lighting for gardens, pathways and landscaping.',
 'Solar garden lights are used for pathways, landscaping and outdoor decoration without the need for mains wiring. Available in a range of styles for homes and commercial landscaping projects.\n\nPlease contact GTC Holdings for the styles and quantities currently available.',
 '[{"title":"No mains wiring","text":"A practical option for pathways and garden areas."},{"title":"Range of styles","text":"Contact us for the designs currently available."}]',
 NULL, NULL, 0, 'uploads/seed/prod-solar-garden.webp', 1, 1, 1,
 'Solar Garden Light in Sri Lanka | GTC Holdings', 'Solar garden lights for pathways, landscaping and outdoor decoration. Supplied for retail and wholesale customers.', 3),
(4, 'Solar Wall Light', 'solar-wall-light', 1,
 'A wall-mounted solar lighting option for entrances, walls and boundary areas.',
 'Solar wall lights are mounted on exterior walls for entrance lighting, boundary areas and general outdoor illumination. They are a practical choice where a permanent power supply is difficult to arrange.\n\nContact us for the models available and bulk pricing.',
 '[{"title":"Wall-mounted design","text":"Suitable for entrances, walls and boundary areas."},{"title":"Bulk orders","text":"Wholesale pricing available on request."}]',
 NULL, NULL, 0, 'uploads/seed/prod-solar-wall.webp', 1, 1, 1,
 'Solar Wall Light in Sri Lanka | GTC Holdings', 'Wall-mounted solar lighting for entrances, walls and boundary areas. Contact GTC Holdings for models and pricing.', 4),
(5, 'Portable Solar Power Station', 'portable-solar-power-station', 1,
 'A portable power option for outdoor use, camping and backup supply.',
 'Portable solar power stations can be used for outdoor activities, camping and as a backup power option for small devices. They can be paired with solar panels for charging away from mains power.\n\nContact GTC Holdings for the capacities and models currently available.',
 '[{"title":"Portable","text":"Designed for outdoor, camping and backup use."},{"title":"Solar compatible","text":"Can be paired with solar panels for charging."}]',
 NULL, NULL, 0, 'uploads/seed/prod-solar-station.webp', 0, 1, 1,
 'Portable Solar Power Station in Sri Lanka | GTC Holdings', 'Portable solar power stations for outdoor, camping and backup power. Contact GTC Holdings for available models.', 5),
(6, 'Hydraulic Floor Jack', 'hydraulic-floor-jack', 2,
 'A hydraulic floor jack for garages, workshops and vehicle maintenance.',
 'Hydraulic floor jacks are used in garages, workshops and service stations for lifting vehicles during maintenance and repair work. GTC Holdings supplies floor jacks for professional and home workshops.\n\nPlease contact us for the capacities and models currently available.',
 '[{"title":"Workshop use","text":"Suitable for garages and vehicle service work."},{"title":"Wholesale supply","text":"Available for resellers and workshops."}]',
 NULL, NULL, 0, 'uploads/seed/prod-auto-jack.webp', 1, 1, 1,
 'Hydraulic Floor Jack in Sri Lanka | GTC Holdings', 'Hydraulic floor jacks for garages, workshops and vehicle maintenance. Supplied for retail and wholesale customers.', 6),
(7, 'Automotive Tool Kit', 'automotive-tool-kit', 2,
 'Hand tools and workshop equipment for vehicle maintenance and repair.',
 'Automotive tool kits and workshop equipment for vehicle maintenance, repair and general garage work. Available for individual buyers and for resellers looking for regular supply.\n\nContact GTC Holdings for the tool sets currently available.',
 '[{"title":"For workshops and homes","text":"Suitable for professional and personal use."},{"title":"Reseller supply","text":"Regular wholesale supply available."}]',
 NULL, NULL, 0, 'uploads/seed/prod-auto-tools.webp', 0, 1, 1,
 'Automotive Tool Kit in Sri Lanka | GTC Holdings', 'Automotive tools and workshop equipment for vehicle maintenance and repair. Wholesale and retail supply.', 7),
(8, 'Car Accessories', 'car-accessories', 2,
 'Interior and exterior vehicle accessories for cars and light vehicles.',
 'A range of car accessories for interior and exterior use. GTC Holdings supplies automotive accessories for retailers, resellers and vehicle owners across Sri Lanka.\n\nPlease contact us for the accessory range currently available.',
 '[{"title":"Wide range","text":"Interior and exterior accessories for vehicles."},{"title":"Retail and wholesale","text":"Suitable for shops and resellers."}]',
 NULL, NULL, 0, 'uploads/seed/prod-auto-accessories.webp', 0, 1, 1,
 'Car Accessories in Sri Lanka | GTC Holdings', 'Car and vehicle accessories for retail and wholesale customers. Contact GTC Holdings for the available range.', 8),
(9, 'Portable Power Inverter', 'portable-power-inverter', 3,
 'A portable inverter for backup power and off-grid electrical supply.',
 'Portable power inverters are used for backup power and for supplying small electrical equipment away from mains power. Suitable for homes, small businesses and outdoor use.\n\nContact GTC Holdings for the capacities currently available.',
 '[{"title":"Backup power","text":"Suitable for homes and small businesses."},{"title":"Specifications on request","text":"Contact us for available capacities."}]',
 NULL, NULL, 0, 'uploads/seed/prod-elec-inverter.webp', 1, 1, 1,
 'Portable Power Inverter in Sri Lanka | GTC Holdings', 'Portable power inverters for backup power and off-grid electrical supply. Contact GTC Holdings for available capacities.', 9),
(10, 'Rechargeable Emergency Light', 'rechargeable-emergency-light', 3,
 'A rechargeable lighting option for power failures and emergency use.',
 'Rechargeable emergency lights provide lighting during power failures and in locations without a reliable electricity supply. A practical option for homes, shops and small businesses.\n\nContact us for the models and quantities available.',
 '[{"title":"Rechargeable","text":"For use during power failures and emergencies."},{"title":"Bulk supply","text":"Wholesale orders available on request."}]',
 NULL, NULL, 0, 'uploads/seed/prod-elec-emergency.webp', 0, 1, 1,
 'Rechargeable Emergency Light in Sri Lanka | GTC Holdings', 'Rechargeable emergency lighting for power failures and locations without reliable electricity. Retail and wholesale supply.', 10),
(11, 'Portable Gas Cooker', 'portable-gas-cooker', 4,
 'A portable gas cooker for household, outdoor and camping use.',
 'Portable gas cookers are suitable for household use, outdoor cooking and camping. GTC Holdings supplies portable cookers and related household products for retail and wholesale buyers.\n\nPlease contact us for the models currently available.',
 '[{"title":"Portable design","text":"Suitable for household and outdoor use."},{"title":"General merchandise","text":"Part of our imported household range."}]',
 NULL, NULL, 0, 'uploads/seed/prod-home-cooker.webp', 0, 1, 1,
 'Portable Gas Cooker in Sri Lanka | GTC Holdings', 'Portable gas cookers for household, outdoor and camping use. Supplied for retail and wholesale customers.', 11),
(12, 'Camping Lantern', 'camping-lantern', 4,
 'A portable lantern for camping, outdoor activities and emergency use.',
 'Portable lanterns for camping, outdoor activities and emergency lighting. Available as part of the general merchandise range supplied by GTC Holdings.\n\nContact us for the styles and quantities currently available.',
 '[{"title":"Outdoor use","text":"Suitable for camping and outdoor activities."},{"title":"Range of styles","text":"Contact us for the models available."}]',
 NULL, NULL, 0, 'uploads/seed/prod-home-camping.webp', 0, 1, 1,
 'Camping Lantern in Sri Lanka | GTC Holdings', 'Portable camping lanterns for outdoor activities and emergency use. Retail and wholesale supply.', 12)
